Find the '0-15' header in Sheet1's header row and copy the values in that column for rows 6-10 into B6:B10. Write blanks as None and copy the source cells' styles to B. Save the modified workbook to OUT.

```python
import shutil
import openpyxl
from copy import copy
from openpyxl.utils import get_column_letter

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

ws = wb["Sheet1"]
vws = vals["Sheet1"]

def norm(v):
    if v is None:
        return None
    if isinstance(v, str):
        v = v.strip()
        return v if v else None
    if isinstance(v, float) and v.is_integer():
        return int(v)
    return v

src_col = None

# Primary: locate the header in row 5.
for col in range(1, vws.max_column + 1):
    v = vws.cell(row=5, column=col).value
    if v is not None and str(v).strip() == "0-15":
        src_col = col
        break

# Fallback: search the hinted data region.
if src_col is None:
    for row in vws.iter_rows(
        min_row=1,
        max_row=min(11, vws.max_row),
        min_col=1,
        max_col=min(12, vws.max_column)
    ):
        for cell in row:
            if cell.value is not None and str(cell.value).strip() == "0-15":
                src_col = cell.column
                break
        if src_col is not None:
            break

answer_rows = list(range(6, 11))

if src_col is not None:
    for r in answer_rows:
        src = vws.cell(row=r, column=src_col)
        dst = ws.cell(row=r, column=2)

        dst.value = norm(src.value)

        # Preserve the source column formatting in the answer cells.
        dst.font = copy(src.font)
        dst.border = copy(src.border)
        dst.fill = copy(src.fill)
        dst.number_format = src.number_format
        dst.protection = copy(src.protection)
        dst.alignment = copy(src.alignment)

    src_letter = get_column_letter(src_col)
    if src_letter in vws.column_dimensions:
        width = vws.column_dimensions[src_letter].width
        if width is not None:
            ws.column_dimensions["B"].width = width
else:
    # Robust fallback: compute the 0-15 counts from RawData by segment.
    if "RawData" in vals.sheetnames:
        raw = vals["RawData"]
        seg_col = None
        bifur_col = None

        for cell in raw[1]:
            if cell.value is None:
                continue
            h = str(cell.value).strip()
            if h == "Seg":
                seg_col = cell.column
            elif h == "AgeBifur":
                bifur_col = cell.column

        if bifur_col is None:
            for row in raw.iter_rows(min_row=2, max_row=raw.max_row):
                for cell in row:
                    if cell.value is not None and str(cell.value).strip() == "0-15":
                        bifur_col = cell.column
                        break
                if bifur_col is not None:
                    break

        if seg_col is not None and bifur_col is not None:
            counts = {}
            for row in raw.iter_rows(min_row=2, max_row=raw.max_row):
                seg = row[seg_col - 1].value
                bif = row[bifur_col - 1].value
                if seg is None or bif is None:
                    continue
                seg = str(seg).strip()
                bif = str(bif).strip()
                if bif == "0-15":
                    counts[seg] = counts.get(seg, 0) + 1

            for r in answer_rows:
                label = vws.cell(row=r, column=1).value
                label = str(label).strip() if label is not None else ""
                c = counts.get(label, 0)
                ws.cell(row=r, column=2).value = c if c else None
        else:
            for r in answer_rows:
                ws.cell(row=r, column=2).value = None
    else:
        for r in answer_rows:
            ws.cell(row=r, column=2).value = None

wb.save(OUT)

print("src_col:", src_col)
print("B6:B10:", [ws.cell(row=r, column=2).value for r in answer_rows])
